INSERT INTO "public"."properties" ("id", "name", "description", "property_type", "category_id", "price", "image_url", "location", "beds", "baths", "sqft", "is_featured", "created_at") VALUES ('1', 'QuaintQuarters Living', 'QuaintQuarters Living: Experience the perfect blend of charm and convenience in our cozy studio apartment. Thoughtfully designed for comfort and style, this modern urban haven maximizes space and natural light. Enjoy community amenities and easy access to the city's vibrant scene, where every detail is crafted for your joy.', 'studio', '2', '404.90', 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=700&q=80', '20 Rue de Monttessuy, 75007 Paris', '2', '1', '1500', 'true', '2025-06-24 20:26:28.734709+00'), ('2', 'Urban Retreat', 'Modern studio in the heart of downtown. Perfect for young professionals seeking a convenient and stylish living space with all amenities within walking distance.', 'studio', '1', '350.00', 'https://images.unsplash.com/photo-1598928636135-d146006ff4be?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=700&q=80', '37 Quai Branly, 75007 Paris', '1', '1', '500', 'false', '2025-06-24 20:26:28.734709+00'), ('3', 'Sunset Studio', 'Beautiful studio with amazing sunset views. This cozy space offers the perfect balance of comfort and style with large windows that flood the apartment with natural light.', 'studio', '3', '380.00', 'https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=700&q=80', '93 Quai d'Orsay, 75007 Paris', '1', '1', '550', 'true', '2025-06-24 20:26:28.734709+00'), ('4', 'Radiant Heights', 'Luxurious condo with premium furnishings and finishes. This spacious unit features high ceilings, hardwood floors, and a gourmet kitchen with top-of-the-line appliances.', 'con